  margin: 0;
  font-size: clamp(1.8rem, 4vw, 2.8rem);
  line-height: 1.15;
  overflow-wrap: anywhere;
}
.member-identity-info > p {
  color: var(--muted);
  display: flex;
  flex-wrap: wrap;
  gap: 8px 24px;
  margin: 12px 0 16px;
}
.member-identity-info > p span {
  border-left: 1px solid var(--line);
