  const input = [
    party("Other", "5.00"),
    {
      ...party("Labour (Co-op)", "72400"),
      entryCount: 11,
      unknownAmountCount: 2,
    },
    party("Other", "10"),
    { ...party("Labour", "546500"), entryCount: 93, unknownAmountCount: 3 },
    party("Labour Co-op", "1"),
  ];
