test.describe("component palettes", () => {
  test.use({ development: true });
  test("updates an open gallery and retains local accents and readable states", async ({ page }) => {
    await page.emulateMedia({ colorScheme: "dark" });
    await page.goto("/design-system", { waitUntil: "networkidle" });
    const canvas = page.locator(".swatch").filter({ hasText: "--canvas" });
    await expect(canvas).toContainText("#000");
    for (const colorScheme of ["light", "dark"] as const) {
      await page.emulateMedia({ colorScheme });
      await expect(page.locator("html")).toHaveCSS("color-scheme", colorScheme);
      await expect(canvas).toContainText(colorScheme === "light" ? "#e9e4ed" : "#000");
      const date = page.getByLabel("Registered from", { exact: true });
      await expect(date).toHaveCSS("color-scheme", colorScheme);
      const member = page.getByRole("link", { name: "Search MPs and funders", exact: true });
      const funder = page.getByRole("link", { name: "Find a funder", exact: true });
      expect(await member.evaluate((node) => getComputedStyle(node).backgroundColor)).not.toBe(await funder.evaluate((node) => getComputedStyle(node).backgroundColor));
      for (const control of [date, member, funder]) {
        expect(await contrast(control)).toBeGreaterThanOrEqual(4.5);
      }
      for (const button of [member, funder]) {
        await button.hover();
        expect(await contrast(button)).toBeGreaterThanOrEqual(4.5);
      }
      await page.locator(".entity-icon").first().hover();
      const tooltip = page.locator(".entity-tooltip > span").first();
      await expect(tooltip).toBeVisible();
      expect(await contrast(tooltip)).toBeGreaterThanOrEqual(4.5);
      await page.mouse.move(0, 0);
    }
  });
});

for (const colorScheme of ["light", "dark"] as const) {
  test(`${colorScheme} initial canvas and metadata work without JavaScript`, async ({ browser, baseURL }) => {
    const context = await browser.newContext({ javaScriptEnabled: false, colorScheme });
    const page = await context.newPage();
    await page.goto(`${baseURL}/`);
    const expected = colorScheme === "light" ? "rgb(233, 228, 237)" : "rgb(0, 0, 0)";
    await expect(page.locator("html")).toHaveCSS("background-color", expected);
    await expect(page.locator("html")).toHaveCSS("color-scheme", colorScheme);
    await expect(page.locator(`meta[name="theme-color"][media="(prefers-color-scheme: ${colorScheme})"]`)).toHaveAttribute("content", colorScheme === "light" ? "#e9e4ed" : "#000000");
    await page.route("**/*.css", (route) => route.abort());
    await page.reload();
    await expect(page.locator("html")).toHaveCSS("background-color", expected);
    await context.close();
  });
}
